def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # If opponent started with D, assume always D and defect all.
    if history[0][1] == 'D':
        return 'D'

    # Check if opponent has ever defected
    opp_defected = False
    for i in range(n):
        if history[i][1] == 'D':
            opp_defected = True
            break

    if not opp_defected:
        # Opponent has been perfectly cooperative so far.
        if n <= 4:
            return 'C'
        if n == 5:
            return 'D'
        if n == 6:
            return 'C'
        # n >= 7
        # Check if opponent defected after our test (round 5)
        opp_defected_after_test = False
        for i in range(6, n):
            if history[i][1] == 'D':
                opp_defected_after_test = True
                break
        if opp_defected_after_test:
            # They retaliated. Cooperate to restore mutual cooperation.
            if n == 99:
                return 'D'
            return 'C'
        else:
            # They still haven't retaliated. Exploit.
            return 'D'
    else:
        # Opponent has defected at some point.
        # Punish only if they defected in the last two rounds.
        if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'
        if n == 99:
            return 'D'
        return 'C'
